package ciot

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math/big"
	"time"
)

// Freight floor (spec section 7): piso = distance x CCD + CC; with empty return, plus 0.92 x distance x CCD.
// Coefficients live in a versioned JSON table (floor_table.json) loaded at runtime. The embedded default was
// generated by script from the owner's reference implementation (ANTT calculator, Res. 5.867/2020 Anexo II as
// amended by 6.084/2026), never typed by hand; an unverified table is still refused.

// EmptyReturnFactor is the 0.92 empty-return surcharge on distance x CCD.
const EmptyReturnFactor = "0.92"

// maxAxlesInTable is the last axle column of Anexo II; larger requested counts resolve to it.
const maxAxlesInTable = 9

// ErrFloorUnverified: the table is not marked verified against the official publication.
var ErrFloorUnverified = errors.New("ciot: freight floor table is not verified against the official ANTT publication")

// ErrFloorNoCoefficient: no coefficient for the combination (unknown cargo type, or a row with no value at all).
var ErrFloorNoCoefficient = errors.New("ciot: no freight floor coefficient for the combination")

//go:embed floor_table.json
var defaultFloorJSON []byte

// FloorRow holds the coefficients of one (composition, high performance, cargo type); Axles maps the axle count to
// the coefficients. A missing axle count is a blank cell. CCD and CC are decimal text (exact, no float).
// The four Anexo II tables: A = composition yes, high performance no; B = no/no; C = yes/yes; D = no/yes.
type FloorRow struct {
	Composition     bool                `json:"composition"`      // Sim: automotor + implemento, or simple truck (A/C)
	HighPerformance bool                `json:"high_performance"` // Sim: alto desempenho (C/D)
	CargoType       int                 `json:"cargo_type"`
	Axles           map[int]FloorCoeffs `json:"axles"`
}

// FloorCoeffs: CCD is per km, CC is a fixed amount in BRL.
type FloorCoeffs struct {
	CCD string `json:"ccd"`
	CC  string `json:"cc"`
}

// FloorTable is the versioned table.
type FloorTable struct {
	Version   string     `json:"version"`
	ValidFrom string     `json:"valid_from"` // yyyy-MM-dd
	Source    string     `json:"source"`
	Verified  bool       `json:"verified"`
	Rows      []FloorRow `json:"rows"`
}

// LoadFloorTable decodes and validates a table.
func LoadFloorTable(r io.Reader) (*FloorTable, error) {
	var t FloorTable
	if err := json.NewDecoder(r).Decode(&t); err != nil {
		return nil, fmt.Errorf("ciot: floor table: %w", err)
	}
	if _, err := ParseDate(t.ValidFrom); err != nil || t.Version == "" {
		return nil, errors.New("ciot: floor table needs version and valid_from")
	}
	for _, row := range t.Rows {
		for ax, c := range row.Axles {
			for _, v := range []string{c.CCD, c.CC} {
				if _, ok := new(big.Rat).SetString(v); !ok {
					return nil, fmt.Errorf("ciot: floor table: bad coefficient %q (axles %d)", v, ax)
				}
			}
		}
	}
	return &t, nil
}

// DefaultFloorTable is the embedded table (verified, valid from 2026-07-17).
func DefaultFloorTable() *FloorTable {
	t, err := LoadFloorTable(bytesReader(defaultFloorJSON))
	if err != nil {
		panic(err) // the embedded file is covered by a test
	}
	return t
}

// FloorInput is one calculation.
type FloorInput struct {
	Composition     bool
	HighPerformance bool
	CargoType       int
	Axles           int
	DistanceKm      int
	EmptyReturn     bool
	At              time.Time // validity check; zero skips it
}

// FloorResult carries the minimum in cents, the table version and validity used, and the axle column applied.
type FloorResult struct {
	Cents            int64 // total: OutboundCents + EmptyReturnCents
	OutboundCents    int64
	EmptyReturnCents int64
	TableVersion     string
	ValidFrom        string
	AxlesUsed        int
}

// Calculate returns the floor in integer cents (rounded half up). It refuses an unverified table.
func (t *FloorTable) Calculate(in FloorInput) (FloorResult, error) {
	if !t.Verified {
		return FloorResult{}, ErrFloorUnverified
	}
	return t.calculate(in)
}

// calculate is Calculate without the verification gate (synthetic-table tests).
func (t *FloorTable) calculate(in FloorInput) (FloorResult, error) {
	if !in.At.IsZero() {
		if from, _ := ParseDate(t.ValidFrom); in.At.Before(from) {
			return FloorResult{}, fmt.Errorf("ciot: floor table %s is valid from %s", t.Version, t.ValidFrom)
		}
	}
	var coeffs *FloorCoeffs
	axlesUsed := 0
	for _, row := range t.Rows {
		if row.Composition == in.Composition && row.HighPerformance == in.HighPerformance && row.CargoType == in.CargoType {
			coeffs, axlesUsed = row.resolveAxles(in.Axles)
			break
		}
	}
	if coeffs == nil {
		return FloorResult{}, ErrFloorNoCoefficient
	}
	ccd, _ := new(big.Rat).SetString(coeffs.CCD)
	cc, _ := new(big.Rat).SetString(coeffs.CC)
	perKm := new(big.Rat).Mul(new(big.Rat).SetInt64(int64(in.DistanceKm)), ccd)
	// Each leg is rounded to cents on its own, as the ANTT calculator publishes them; the total is their sum.
	outbound := roundCents(new(big.Rat).Add(perKm, cc))
	var empty int64
	if in.EmptyReturn {
		f, _ := new(big.Rat).SetString(EmptyReturnFactor)
		empty = roundCents(new(big.Rat).Mul(f, perKm))
	}
	return FloorResult{Cents: outbound + empty, OutboundCents: outbound, EmptyReturnCents: empty,
		TableVersion: t.Version, ValidFrom: t.ValidFrom, AxlesUsed: axlesUsed}, nil
}

// roundCents converts reais to integer cents, rounding half up.
func roundCents(reais *big.Rat) int64 {
	x := new(big.Rat).Mul(reais, big.NewRat(100, 1))
	x.Add(x, big.NewRat(1, 2))
	return new(big.Int).Quo(x.Num(), x.Denom()).Int64()
}

// resolveAxles applies Anexo II Nota 1: the nearest defined axle column below the requested count, above only when
// none below; the same rule covers blank cells. Counts above 9 resolve to 9, count 1 to 2.
func (r FloorRow) resolveAxles(axles int) (*FloorCoeffs, int) {
	if axles < 1 {
		return nil, 0
	}
	start := min(axles, maxAxlesInTable)
	for ax := start; ax >= 1; ax-- {
		if c, ok := r.Axles[ax]; ok {
			return &c, ax
		}
	}
	for ax := start + 1; ax <= maxAxlesInTable; ax++ {
		if c, ok := r.Axles[ax]; ok {
			return &c, ax
		}
	}
	return nil, 0
}

func bytesReader(b []byte) io.Reader { return bytes.NewReader(b) }
